// Fills the classify prompt from prompts/classify.md with the normalized message.
const config = $("Config").first().json;
const message = $json.message;
const userText = config.classify_user.replace(/\{\{(\w+)\}\}/g, (placeholder, key) => String(message[key] ?? ""));
return {
  json: {
    message,
    request: {
      systemInstruction: { parts: [{ text: config.classify_system }] },
      contents: [{ role: "user", parts: [{ text: userText }] }],
      generationConfig: { responseMimeType: "application/json", maxOutputTokens: config.max_output_tokens, temperature: 0.2 },
    },
  },
};

// Takes the text of the first candidate from the Gemini response.
const parts = $json.candidates?.[0]?.content?.parts ?? [];
return {
  json: {
    message: $("Build classify request").item.json.message,
    ai_text: parts.map((part) => part.text ?? "").join(""),
  },
};

